class Solution {
    bool possible(const vector<int>& stations, int k, double d) {
        int count = 0;
        for (int i = 0; i < (int)stations.size() - 1; i++) {
            count += (int)((stations[i + 1] - stations[i]) / d);
        }
        return count <= k;
    }
public:
    double minmaxGasDist(vector<int>& stations, int k) {
        double left = 0.0, right = stations.back() - stations.front();
        for (int iter = 0; iter < 80; iter++) {
            double mid = (left + right) / 2.0;
            if (possible(stations, k, mid)) right = mid;
            else left = mid;
        }
        return left;
    }
};

class Solution {
    private boolean possible(int[] stations, int k, double d) {
        int count = 0;
        for (int i = 0; i < stations.length - 1; i++) {
            count += (int) ((stations[i + 1] - stations[i]) / d);
        }
        return count <= k;
    }
    public double minmaxGasDist(int[] stations, int k) {
        double left = 0.0, right = stations[stations.length - 1] - stations[0];
        for (int iter = 0; iter < 80; iter++) {
            double mid = (left + right) / 2.0;
            if (possible(stations, k, mid)) right = mid;
            else left = mid;
        }
        return left;
    }
}

var minmaxGasDist = function(stations, k) {
    let left = 0.0;
    let right = stations[stations.length - 1] - stations[0];
    function possible(d) {
        let count = 0;
        for (let i = 0; i < stations.length - 1; i++) {
            count += Math.floor((stations[i + 1] - stations[i]) / d);
        }
        return count <= k;
    }
    for (let iter = 0; iter < 80; iter++) {
        const mid = (left + right) / 2.0;
        if (possible(mid)) right = mid;
        else left = mid;
    }
    return left;
};
